'use strict';const cases=['single','stack'];function setup(c,s,variant){s.phase='MAIN_PHASE';s.turnNumber=3;s.activePlayerId='P1';s.pendingEffect=null;for(const p of s.playerOrder)for(const z of ['hand','field','food','territory','discard'])s.player(p)[z]=[];s.player('P1').availableCost=0;function put(id,z,p='P1'){const d=c.getCardDefinition(id),x=new c.CardInstance({instanceId:s.nextInstanceId(),cardId:id,ownerId:p,controllerId:p,zone:z,baseHp:d.baseHp,currentHp:d.baseHp});s.player(p)[z.toLowerCase()].push(x);return x;}put('set1_003','FIELD').currentHp-=100;put('kabutomushi','FIELD');put('namitentou','FIELD','P2');put('set8_064','HAND');if(variant==='stack')put('set8_064','HAND');}module.exports={cases,setup};
